
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_mgga_x_msb86bl_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("mgga_x_msb86bl", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-4.569127065389579e+00, -4.479447965664636e+00, -4.353839628229057e+00, -4.179955249055531e+00, -3.943261997680699e+00, -3.628779637779478e+00, -3.225203568474476e+00, -2.732357832713904e+00, -2.170384232984339e+00, -1.567469650043090e+00, -1.009366946951171e+00, -6.749788272819607e-01, -6.037890659410620e-01, -5.110464432262103e-01, -3.652655458050543e-01, -2.292912724105579e-01, -1.342840654534711e-01, -6.389429179550539e-02, -2.092993970532813e-02, -4.678538922390053e-03]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


